use js_sys::Uint8Array;
use wasm_bindgen::prelude::*;

// Binds this crate as a wasm-bindgen module so that, with
// `wasm-bindgen --target nodejs`, Node.js can load it and call
// the exported functions from JavaScript.
#[wasm_bindgen(module)]
extern "C" {
}

// Exposed to JavaScript under the camelCase name `xorCipher`.
//
// Generated TypeScript declaration:
//     export function xorCipher(data: Uint8Array, key: Uint8Array): Uint8Array;
#[wasm_bindgen(name = "xorCipher")]
pub fn xor_cipher(data: Uint8Array, key: Uint8Array) -> Uint8Array {
    // Copy both inputs into owned buffers. The function only reads
    // from them, so the caller's `data` and `key` are never modified.
    let data: Vec<u8> = data.to_vec();
    let key: Vec<u8> = key.to_vec();

    let mut out = Vec::with_capacity(data.len());

    if key.is_empty() {
        // Empty key: xoring with an "identity" is a no-op, so return an
        // unchanged copy of `data` (also avoids a divide-by-zero in `%`).
        out.extend_from_slice(&data);
    } else {
        // Repeating key: apply the key byte for position `i`.
        for i in 0..data.len() {
            out.push(data[i] ^ key[i % key.len()]);
        }
    }

    // Allocates a brand-new buffer, so the result is a NEW
    // `Uint8Array` of length `data.len()` (empty if `data` is empty).
    Uint8Array::from(&out)
}
```

